@msig trait AcquisitionEvidenceQualification_coordinationProcess_acquisitionEvidenceQualification_TestApi {

  def BeforeEntrypoint(): Unit = {
    Art.initTest(Arch.EITMonitoringAcquisitionCoordinatorSystem_Instance_coordinationProcess_acquisitionEvidenceQualification)
  }

  def AfterEntrypoint(): Unit = {
    Art.finalizeTest(Arch.EITMonitoringAcquisitionCoordinatorSystem_Instance_coordinationProcess_acquisitionEvidenceQualification)
  }

  def testCompute(): Unit = {
    Art.manuallyClearOutput()
    Art.testCompute(Arch.EITMonitoringAcquisitionCoordinatorSystem_Instance_coordinationProcess_acquisitionEvidenceQualification)
  }

  def testInitialise(): Unit = {
    Art.manuallyClearOutput()
    Art.testInitialise(Arch.EITMonitoringAcquisitionCoordinatorSystem_Instance_coordinationProcess_acquisitionEvidenceQualification)
  }

  /** helper function to set the values of all input ports.
   * @param calibrationSample payload for data port calibrationSample
   * @param impedanceSample payload for data port impedanceSample
   */
  def put_concrete_inputs(calibrationSample : EIT_Acquisition_Coordinator.CalibrationSample,
                          impedanceSample : EIT_Acquisition_Coordinator.ImpedanceSample): Unit = {
    put_calibrationSample(calibrationSample)
    put_impedanceSample(impedanceSample)
  }


  /** helper function to check AcquisitionEvidenceQualification_coordinationProcess_acquisitionEvidenceQualification's
   * output ports.  Use named arguments to check subsets of the output ports.
   * @param acquisitionEvidence method that will be called with the value of the outgoing data
   *        port 'acquisitionEvidence'.
   */
  def check_concrete_output(acquisitionEvidence: EIT_Acquisition_Coordinator.AcquisitionEvidence.Type => B): Unit = {
    var testFailures: ISZ[ST] = ISZ()

    val acquisitionEvidenceValue: EIT_Acquisition_Coordinator.AcquisitionEvidence.Type = get_acquisitionEvidence().get
    if(!acquisitionEvidence(acquisitionEvidenceValue)) {
      testFailures = testFailures :+ st"'acquisitionEvidence' did not match expected: value of the outgoing data port is ${acquisitionEvidenceValue}"
    }

    assert(testFailures.isEmpty, st"${(testFailures, "\n")}".render)
  }


  // setter for in DataPort
  def put_calibrationSample(value : EIT_Acquisition_Coordinator.CalibrationSample): Unit = {
    Art.insertInInfrastructurePort(Arch.EITMonitoringAcquisitionCoordinatorSystem_Instance_coordinationProcess_acquisitionEvidenceQualification.operational_api.calibrationSample_Id, EIT_Acquisition_Coordinator.CalibrationSample_Payload(value))
  }

  // setter for in DataPort
  def put_impedanceSample(value : EIT_Acquisition_Coordinator.ImpedanceSample): Unit = {
    Art.insertInInfrastructurePort(Arch.EITMonitoringAcquisitionCoordinatorSystem_Instance_coordinationProcess_acquisitionEvidenceQualification.operational_api.impedanceSample_Id, EIT_Acquisition_Coordinator.ImpedanceSample_Payload(value))
  }

  // getter for out DataPort
  def get_acquisitionEvidence(): Option[EIT_Acquisition_Coordinator.AcquisitionEvidence.Type] = {
    val value: Option[EIT_Acquisition_Coordinator.AcquisitionEvidence.Type] = get_acquisitionEvidence_payload() match {
      case Some(EIT_Acquisition_Coordinator.AcquisitionEvidence_Payload(v)) => Some(v)
      case Some(v) => halt(s"Unexpected payload on port acquisitionEvidence.  Expecting 'EIT_Acquisition_Coordinator.AcquisitionEvidence_Payload' but received ${v}")
      case _ => None[EIT_Acquisition_Coordinator.AcquisitionEvidence.Type]()
    }
    return value
  }

  // payload getter for out DataPort
  def get_acquisitionEvidence_payload(): Option[EIT_Acquisition_Coordinator.AcquisitionEvidence_Payload] = {
    return Art.observeOutInfrastructurePort(Arch.EITMonitoringAcquisitionCoordinatorSystem_Instance_coordinationProcess_acquisitionEvidenceQualification.initialization_api.acquisitionEvidence_Id).asInstanceOf[Option[EIT_Acquisition_Coordinator.AcquisitionEvidence_Payload]]
  }

}
